class Solution {int[]parent,size;long[]offset;int find(int u){if(parent[u]!=u){int p=parent[u];parent[u]=find(p);offset[u]+=offset[p];}return parent[u];}public boolean solve(int n,int[][]edges){parent=new int[n];size=new int[n];offset=new long[n];for(int i=0;i<n;i++){parent[i]=i;size[i]=1;}for(int[]e:edges){int a=find(e[0]),b=find(e[1]);long pu=offset[e[0]],pv=offset[e[1]],bridge=(long)e[2]+pu-pv;if(a==b){if(pv-pu!=e[2])return false;}else if(size[a]>=size[b]){parent[b]=a;offset[b]=bridge;size[a]+=size[b];}else{parent[a]=b;offset[a]=-bridge;size[b]+=size[a];}}return true;}}